            ["Kistengrößen unten verwenden."] = "Use the chest sizes below.",
            ["Breite x Höhe, z.B. 5x2. NICHT kleiner machen als bisher, sonst können Items verloren gehen!"] = "Width x height, e.g. 5x2. Do NOT make it smaller than before, or items may be lost!",
            ["Auf eine Kiste schauen und drücken, um einen Namen einzugeben. Der Name steht als Schild auf der Kiste."] = "Look at a chest and press to enter a name. The name is shown as a sign on the chest.",
            ["Auf die Kiste schauen und drücken: Das Schild wandert zur nächsten Seite (vorne, rechts, hinten, links)."] = "Look at the chest and press: the sign moves to the next side (front, right, back, left).",
            ["In der offenen Kiste auf ein Item zeigen und drücken: Sein Bild erscheint auf dem Schild. Nochmal drücken entfernt es."] = "In the open chest point at an item and press: its picture appears on the sign. Press again to remove it.",
            ["Farbe der Schrift auf der Kiste (Auswahlliste)."] = "Color of the text on the chest (list).",
            ["Schnell verstauen und sortieren per Taste."] = "Quick stack and sort with a key.",
            ["Legt alle Items in Kisten in der Nähe, in denen schon dasselbe Item liegt."] = "Puts all items into chests nearby that already contain the same item.",
            ["Die oberste Inventarreihe (1–8) wird beim Verstauen und Sortieren ignoriert."] = "The top inventory row (1–8) is ignored when stacking and sorting.",
            ["Sortiert dein Inventar und die geöffnete Kiste (Stapel werden zusammengelegt)."] = "Sorts your inventory and the open chest (stacks are merged).",
            ["Im Inventar: Item mit der Maus festhalten und Taste drücken = gelöscht. Ausgerüstetes wird nie gelöscht."] = "In the inventory: hold an item with the mouse and press the key = deleted. Equipped items are never deleted.",
            ["Kompaktere Werkbank-Erweiterungen (wirkt nach Neu-Einloggen)."] = "More compact workbench extensions (takes effect after logging in again).",
            ["Wie weit eine Erweiterung (Hackklotz, Gerbgestell usw.) entfernt stehen darf."] = "How far away an extension (chopping block, tanning rack etc.) may stand.",
            ["0 = Erweiterungen dürfen direkt nebeneinander stehen."] = "0 = extensions may stand right next to each other.",
            ["ca. 1 m"] = "about 1 m",
            ["E am Portal öffnet ein Fenster: Name (bis 30 Zeichen), Ziel (alle Portale der Welt) und Standard-Portal. Der Mod muss dafür auch auf dem Server installiert sein."] = "E at a portal opens a window: name (up to 30 characters), target (all portals of the world) and default portal. The mod must also be installed on the server for this.",
            ["nur Name"] = "name only",
            ["Legst du ein Item in eine Kiste, in der es noch nicht liegt, wandert es in eine Kiste in der Nähe, die es schon hat (oder die gleiche Gruppe, z.B. Holz zu Holz). Die Ziel-Kiste leuchtet kurz rot auf."] = "If you put an item into a chest that does not contain it yet, it moves to a chest nearby that already has it (or the same group, e.g. wood to wood). The target chest briefly glows red.",
            ["Holz zu Holz, Metall zu Metall usw. (Liste unten)."] = "Wood to wood, metal to metal etc. (list below).",
            ["Automatisch gruppiert: fertige Gerichte, Tränke/Met, Trophäen, Munition, Fische, Rüstung und Waffen (auch Schilde, Bögen, Fackeln), Schmuck, Hilfsmittel und Werkzeuge (Gürtel, Wünschelrute, Irrlicht, Schmuckstücke, Hammer, Hacke, Kultivator, Spitzhacken, Angel). Dazu kommen alle pflanzbaren Samen zu \"Samen\" und ungekochte Zwischenprodukte (Teig, ungebackene Pasteten …) zu \"Zutaten\", auch wenn sie nicht in der Liste stehen."] = "Grouped automatically: cooked meals, potions/mead, trophies, ammo, fish, armor and weapons (also shields, bows, torches), trinkets, utilities and tools (belt, wishbone, wisp, trinkets, hammer, hoe, cultivator, pickaxes, fishing rod). On top of that all plantable seeds go to \"Samen\" (seeds) and uncooked intermediate products (dough, unbaked pies …) to \"Zutaten\" (ingredients), even if they are not in the list.",
            ["Format: Gruppenname:Prefab1,Prefab2;Gruppenname2:… (Prefab-Namen wie im Spawn-Befehl)"] = "Format: GroupName:Prefab1,Prefab2;GroupName2:… (prefab names as in the spawn command)",
            ["Hältst du diese Taste beim Einlagern, bleibt das Item in der offenen Kiste."] = "If you hold this key while storing, the item stays in the open chest.",
            ["Restzeit bei Pflanzen und Setzlingen."] = "Time left on plants and saplings.",
            ["Restzeit beim Gären."] = "Time left while fermenting.",
            ["Zeit bis zum nächsten Honig."] = "Time until the next honey.",
            ["Zähmen, Liebe, Trächtigkeit, Erwachsenwerden."] = "Taming, love, pregnancy, growing up.",
            ["nur Zähm-Prozent"] = "only taming percent",
            ["Zeigt oben in der Mitte eine Uhr (ausgeblendet, solange Inventar, Kiste oder Karte offen ist)."] = "Shows a clock at the top center (hidden while inventory, chest or map is open).",
            ["keine Uhr"] = "no clock",
            ["Echte Minuten vom Morgen bis zum Abend. Muss auf dem Server gleich sein (Server-Sync erledigt das)."] = "Real minutes from morning to evening. Must be the same on the server (server sync does that).",
            ["ca. 21 Min"] = "about 21 min",
            ["Echte Minuten vom Abend bis zum Morgen."] = "Real minutes from evening to morning.",
            ["ca. 9 Min"] = "about 9 min",
            ["Zeigt den aktuellen Tag (z.B. Tag 42)."] = "Shows the current day (e.g. Day 42).",
            ["Valheim-Uhrzeit (z.B. 14:30)."] = "Valheim time (e.g. 14:30).",
            ["Uhrzeit deines PCs."] = "Time of your PC.",
            ["false = 12-Stunden-Format (AM/PM)."] = "false = 12-hour format (AM/PM).",
            ["4 Slots neben dem Inventar: Helm, Brust, Beine, Umhang. Angelegte Rüstung belegt dann keinen Inventarplatz mehr. Wirkt nach Neu-Einloggen."] = "4 slots next to the inventory: helmet, chest, legs, cape. Equipped armor no longer takes inventory space. Takes effect after logging in again.",
            ["keine Rüstungsslots"] = "no armor slots",
            ["3 Essensslots neben dem Inventar, Essen per Taste. Wirkt nach Neu-Einloggen."] = "3 food slots next to the inventory, eat with a key. Takes effect after logging in again.",
            ["keine Essensslots"] = "no food slots",
            ["Ein Slot unter dem Essen für einen Schild. Nimmst du eine Einhandwaffe, wird dieser Schild automatisch angelegt (wenn die linke Hand frei ist). Bei Zweihandwaffen und Bögen legt Valheim ihn ab, er bleibt im Slot. Legst du einen anderen Schild an, kommt der in den Slot. Wirkt nach Neu-Einloggen."] = "A slot below the food for a shield. When you take a one-handed weapon, this shield is equipped automatically (if the left hand is free). With two-handed weapons and bows Valheim unequips it, it stays in the slot. If you equip another shield, that one goes into the slot. Takes effect after logging in again.",
            ["Ein Slot unter dem Schmuck für Schlüssel (z.B. Krypta-Schlüssel aus dem Sumpf). Türen öffnen sich wie gewohnt, der Schlüssel belegt aber keinen Inventarplatz. Aufgehobene Schlüssel wandern von selbst hinein. Erkennt alle Schlüssel, die eine Tür braucht – auch aus anderen Mods. Wirkt nach Neu-Einloggen."] = "A slot below the trinket for keys (e.g. the swamp crypt key). Doors open as usual, but the key takes no inventory space. Picked up keys move in by themselves. Detects every key a door needs – also from other mods. Takes effect after logging in again.",
            ["So viele Reihen bekommt das Inventar zusätzlich (je 8 Plätze). Beim Händler gekaufte Reihen kommen obendrauf, höchstens 9 Reihen insgesamt. Wirkt sofort. Achtung: Stellst du den Wert wieder kleiner, fallen Items aus den weggefallenen Reihen auf den Boden."] = "This many extra rows for the inventory (8 slots each). Rows bought from the trader come on top, at most 9 rows in total. Takes effect immediately. Careful: if you lower the value again, items from the removed rows drop to the ground.",
            ["0 (4 Reihen)"] = "0 (4 rows)",
            ["Wie durchsichtig die zweite Leiste auf dem Bildschirm ist. 1 = so wie die normale Schnellleiste, kleiner = durchsichtiger."] = "How transparent the second bar is on screen. 1 = like the normal hotbar, lower = more transparent.",
            ["Holst du deinen Grabstein ab, kommen Essen, zweite Schnellleiste, Rüstung, Schild, Schmuck und Schlüssel wieder in ihre Slots statt ins normale Inventar. Rüstung wird dabei wieder angelegt."] = "When you loot your tombstone, food, second hotbar, armor, shield, trinket and key go back into their slots instead of the normal inventory. Armor is equipped again.",
            ["alles landet im normalen Inventar"] = "everything ends up in the normal inventory",
            ["So viele Minuten dauert es, bis Büsche, Pilze und Disteln aus der Liste nach dem Ernten wieder erntbar sind. Normal sind 300 Minuten (5 Stunden, wie Himbeer- und Blaubeerbüsche im Spiel). Es zählt die Zeit, in der du spielst (Schlafen spult vor). Beispiel: 60 = eine Stunde. Wirkt nach Neu-Einloggen."] = "How many minutes until bushes, mushrooms and thistles from the list can be harvested again. Normal is 300 minutes (5 hours, like raspberry and blueberry bushes in the game). Counts the time you play (sleeping skips ahead). Example: 60 = one hour. Takes effect after logging in again.",
            ["Büsche 300, Pilze/Disteln wachsen gar nicht nach"] = "bushes 300, mushrooms/thistles do not regrow",
            ["kein Schlüssel-Slot"] = "no key slot",
            ["kein Schild-Slot, Schild von Hand anlegen"] = "no shield slot, equip the shield by hand",
            ["2 Slots in der mittleren Spalte: Wünschelrute ODER Irrlicht (normales Hilfsmittel) und Schmuck (Trinket). Angelegtes belegt keinen Inventarplatz. Wirkt nach Neu-Einloggen."] = "2 slots in the middle column: wishbone OR wisp (normal utility) and trinket. Equipped items take no inventory space. Takes effect after logging in again.",
            ["keine Slots"] = "no slots",
            ["Eigener Slot für den Gürtel (Megingiard). Er wirkt dort ZUSÄTZLICH zu Wünschelrute oder Irrlicht – im normalen Spiel geht nur eins davon. Wirkt nach Neu-Einloggen."] = "Own slot for the belt (Megingjord). There it works IN ADDITION to wishbone or wisp – in the normal game only one of them works. Takes effect after logging in again.",
            ["Gürtel teilt sich den Platz mit Wünschelrute/Irrlicht"] = "belt shares the spot with wishbone/wisp",
            ["Isst das Essen aus dem ersten Essensslot."] = "Eats the food from the first food slot.",
            ["Isst das Essen aus dem zweiten Essensslot."] = "Eats the food from the second food slot.",
            ["Isst das Essen aus dem dritten Essensslot."] = "Eats the food from the third food slot.",
            ["Tastenkürzel über den Essensslots, Namen in leeren Rüstungsslots."] = "Key hints above the food slots, names in empty armor slots.",
            ["Zweite Schnellleiste mit 8 eigenen Slots: im Inventarfenster unter den Extra-Slots, auf dem Bildschirm unter der normalen Leiste. Benutzen mit Alt+1 bis Alt+8. Wirkt nach Neu-Einloggen."] = "Second hotbar with 8 own slots: in the inventory window below the extra slots, on screen below the normal hotbar. Use with Alt+1 to Alt+8. Takes effect after logging in again.",
            ["nur eine Schnellleiste"] = "only one hotbar",
            ["Diese Taste halten und 1-8 drücken = Item aus der zweiten Schnellleiste benutzen."] = "Hold this key and press 1-8 = use an item from the second hotbar.",
            ["Fundstellen in Sichtweite erscheinen als Pins auf Minikarte und großer Karte (werden nicht gespeichert). Alles Weitere (Items, andere Orte, vergrabene Erze, große Symbole …) im Radar-Fenster einstellen."] = "Finds in view appear as pins on the minimap and the big map (not saved). Everything else (items, other places, buried ores, large icons …) is set in the radar window.",
            ["Öffnet das Radar-Fenster: dort auswählen, welche Items/Orte gepinnt werden."] = "Opens the radar window: choose there which items/places get pinned.",
            ["Dungeon-Eingänge pinnen (Grabkammern, Trollhöhlen, Krypten, Frosthöhlen …)."] = "Pin dungeon entrances (burial chambers, troll caves, crypts, frost caves …).",
            ["Namen neben den Pins."] = "Names next to the pins.",
            ["Gilt auf dem Server bzw. beim Host: Alle Spieler bekommen beim Einloggen diese Werte. Tasten, Uhr, Extra-Slots, Radar und Inventar-Hilfen werden nicht übertragen."] = "Applies on the server or host: all players get these values when they log in. Keys, clock, extra slots, radar and inventory helpers are not sent.",
            ["Gilt beim Spieler: Werte vom Server ersetzen während der Sitzung die eigenen. Deine Datei wird nicht verändert."] = "Applies to the player: values from the server replace your own during the session. Your file is not changed.",
            ["Im Inventar mit Mausrad-Klick auf ein Item: Es wird Favorit mit der Menge, die gerade im Stapel liegt (gelber Rahmen). Verbrauchst du davon etwas (Essen, Bauen, Herstellen, Pfeile …), wird aus Kisten in der Nähe wieder auf diese Menge aufgefüllt. Nochmal Mausrad-Klick = kein Favorit mehr. Aufgefüllt wird, sobald das Inventar zu ist."] = "In the inventory middle-click an item: it becomes a favorite with the amount currently in the stack (yellow border). When you use some of it (eating, building, crafting, arrows …), it is refilled to that amount from chests nearby. Middle-click again = no longer a favorite. Refilling happens as soon as the inventory is closed.",
            ["keine Favoriten"] = "no favorites",
            ["Taste bzw. Maustaste zum Markieren (Mouse2 = Mausrad-Klick). Maus über das Item im Inventar halten und drücken."] = "Key or mouse button for marking (Mouse2 = middle mouse button). Hold the mouse over the item in the inventory and press.",
            ["Aus Kisten in diesem Umkreis wird aufgefüllt (keine privaten Kisten anderer, keine Grabsteine, keine gerade geöffneten Kisten)."] = "Refills from chests within this radius (no private chests of others, no tombstones, no chests that are open right now).",
            ["Beim Draufzeigen auf Waffe, Schild oder Rüstung (auch an der Werkbank) steht unten der Vergleich zu dem, was du gerade anhast: Schaden, Blocken oder Rüstung, grün = besser, rot = schlechter."] = "When pointing at a weapon, shield or armor (also at the workbench) the tooltip shows the comparison to what you are wearing: damage, block or armor, green = better, red = worse.",
            ["kein Vergleich"] = "no comparison",
            ["An Werkbank, Schmiede, Kessel usw. steckt Valheim Waffe und Schild weg. Mit true bleiben sie in der Hand."] = "At workbench, forge, cauldron etc. Valheim puts away weapon and shield. With true they stay in your hands.",
            ["Waffen werden weggesteckt"] = "weapons are put away",
            ["Die Haltbarkeits-Leiste unter Waffen, Werkzeugen und Rüstung (Inventar und Schnellleiste) färbt sich von Grün (neu) über Gelb bis Rot (fast kaputt)."] = "The durability bar below weapons, tools and armor (inventory and hotbar) changes color from green (new) over yellow to red (almost broken).",
            ["Leiste immer gleiche Farbe"] = "bar always the same color",
            ["Eigener Skill „Erkunden“: Je mehr Karte du neu aufdeckst, desto höher steigt er – und desto weiter um dich herum wird die Karte aufgedeckt."] = "Own skill \"Exploring\": the more map you uncover, the higher it rises – and the farther around you the map is uncovered.",
            ["fester Radius 100 m, kein Skill"] = "fixed radius 100 m, no skill",
            ["So weit wird die Karte am Anfang aufgedeckt."] = "This is how far the map is uncovered at the start.",
            ["So weit wird die Karte bei Skill 100 aufgedeckt. Dazwischen wächst der Radius gleichmäßig mit dem Skill."] = "This is how far the map is uncovered at skill 100. In between the radius grows evenly with the skill.",
            ["Wie schnell der Skill steigt. 1 = etwa 20 Stunden neues Land erkunden bis Skill 100, 2 = doppelt so schnell."] = "How fast the skill rises. 1 = about 20 hours of exploring new land until skill 100, 2 = twice as fast.",
            ["Eigener Skill „Segeln“: steigt, solange du am Steuer stehst und das Schiff fährt. Mit dem Skill wird das Schiff schneller (Segel und Rudern)."] = "Own skill \"Sailing\": rises while you stand at the helm and the ship is moving. With the skill the ship gets faster (sail and rowing).",
            ["kein Skill"] = "no skill",
            ["So viel schneller ist das Schiff bei Skill 100. Dazwischen gleichmäßig."] = "This much faster is the ship at skill 100. Evenly in between.",
            ["0"] = "0",
            ["Wie schnell der Skill steigt. 1 = etwa 20 Stunden Fahrt bis Skill 100."] = "How fast the skill rises. 1 = about 20 hours of sailing until skill 100.",
            ["Eigener Skill „Zähmen“: steigt beim Zähmen, Füttern und Verlieben deiner Tiere (in deiner Nähe). Zahme Tiere in deiner Nähe (50 m) nehmen weniger Schaden und machen mehr Schaden."] = "Own skill \"Taming\": rises when taming, feeding and breeding your animals (near you). Tamed animals near you (50 m) take less damage and deal more damage.",
            ["So viel weniger Schaden nehmen zahme Tiere bei Skill 100."] = "This much less damage tamed animals take at skill 100.",
            ["So viel mehr Schaden machen zahme Tiere bei Skill 100."] = "This much more damage tamed animals deal at skill 100.",
            ["Wie schnell der Skill steigt."] = "How fast the skill rises.",
        };
    }
}
